import type { ReactNode } from 'react'
import { useLocation } from 'react-router'
import { Link } from 'react-router'
import { Box, HoverCard, Skeleton } from '@chakra-ui/react'

import { useRefVideoAutoLoopPlay } from '~/ui/parts/VideoView'
import { useRippleEffect, RippleEffect } from '~/ui/parts/effect/RippleEffect'
import { MyYesButton } from '~/ui/parts/MyButton'

/** @jsxImportSource @emotion/react */
import { css } from '@emotion/react'


type ItemLinkProp = {
  path: string;
  id: string;
  thumbnailVideo?: string;
  thumbnailImage?: string;
  children: ReactNode;
}
export function ItemLink(prop: ItemLinkProp) {
  const { path, id, thumbnailVideo, thumbnailImage, children } = prop;
  const { inViewRef, videoRefs } = useRefVideoAutoLoopPlay(1);
  const { targetProp, effectProp } = useRippleEffect<HTMLButtonElement>();
  targetProp.css = [ targetProp.css, styles.link ].flat();
  
  const location = useLocation();
  const url = location.pathname.endsWith(`${path}`) ? `#${id}` : `${path}#${id}`;
  
  return (
    <Link to={url}>
      <HoverCard.Root>
        <HoverCard.Trigger {...targetProp}>
          {children}
          <RippleEffect {...effectProp} />
        </HoverCard.Trigger>
        <HoverCard.Positioner>
          <HoverCard.Content p='0'>
            <MyYesButton as='span' h='fit-content' w='fit-content' paddingTop='0.5em'>
              <Box as='span' ref={inViewRef} css={styles.thumbnail}>
                <Skeleton as='span' />
                {thumbnailImage && <img src={thumbnailImage} loading='lazy' />}
                {thumbnailVideo && <video ref={videoRefs.current[0]} src={thumbnailVideo} playsInline loop muted />}
              </Box>
            </MyYesButton>
          </HoverCard.Content>
        </HoverCard.Positioner>
      </HoverCard.Root>
    </Link>
  )
}


const styles = {
  link: css`
    text-decoration: underline;
    cursor: var(--chakra-cursor-button);
  `,
  thumbnail: css`
    --width: 10em;
    position: relative;
    width: var(--width);
    height: fit-content;
    
    > span {
      display: inline-block;
      width: var(--width);
      aspect-ratio: 16 / 9;
    }
    > video, > img {
      position: absolute;
      top: 0;
      left: 0;
      width: var(--width);
      aspect-ratio: 16 / 9;
    }
    > img {
      object-fit: contain;
      background-color: black;
    }
  `
} as const
